<script setup lang="ts">
import {ref,onMounted,computed} from 'vue'
import {get,request} from '../api/client'
type Row=Record<string,any>
const props=defineProps<{view:string}>(),rows=ref<Row[]>([]),error=ref(''),notice=ref(''),config=ref<Row|null>(null),statistics=ref<Row|null>(null),page=ref(1),total=ref(0),filter=ref(''),busy=ref(false),capabilities=ref<Row|null>(null)
const titles:Record<string,string>={rules:'用户提醒规则',records:'推送记录',settings:'每日提醒设置',instant:'即时提醒设置',templates:'推送模板',statistics:'强提醒统计',monitor:'通道监控',wecom:'企微任务','wecom-config':'企微配置','wecom-operations':'企微任务处理','wecom-logs':'企微执行记录','wecom-statistics':'企微统计'}
const names:Record<string,string>={PENDING:'待处理',WAITING_AUTH:'等待授权或绑定',SENDING:'提交中',AWAITING_STAFF:'待企微人工执行',PARTIAL:'部分执行',SENT:'已确认发送',ACCEPTED:'平台已接受',FAILED:'失败',UNKNOWN:'结果待核实',CANCELLED:'已取消'}
const listing=computed(()=>['rules','records','wecom','wecom-logs'].includes(props.view)),selected=ref<Row|null>(null),outcome=ref('SENT'),evidence=ref(''),pausing=ref<Row|null>(null),pauseReason=ref('')
const health=ref<Row|null>(null)
const wecomView=computed(()=>props.view.startsWith('wecom')),statRows=computed(()=>(statistics.value?.states||[]).filter((r:Row)=>!wecomView.value||r.channel==='WECom'))
async function load(){error.value='';[config.value,capabilities.value]=await Promise.all([get('/api/v1/admin/reminders/settings'),get('/api/v1/admin/notifications/capabilities')]);config.value!.slots=typeof config.value!.slots==='string'?JSON.parse(config.value!.slots):config.value!.slots;if(listing.value){const d=await get('/api/v1/admin/reminders/'+(props.view==='rules'?'rules':'batches'),{page:page.value,size:20,state:filter.value,channel:wecomView.value?'WECom':''});rows.value=d.items;total.value=d.total}if(['statistics','wecom-statistics'].includes(props.view))statistics.value=await get('/api/v1/admin/reminders/statistics');if(props.view==='monitor')health.value=await get('/api/v1/admin/reminders/health')}
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function save(){await act(async()=>{await request('PUT','/api/v1/admin/reminders/settings',{...config.value,expectedVersion:config.value!.lockVersion});await load();notice.value='设置已保存'})}
async function tick(){await act(async()=>{const result=await request('POST','/api/v1/admin/reminders/tick',{});await load();notice.value=`本次规划 ${result.planned} 个批次，处理 ${result.processed} 个。${result.localSimulation?'结果来自本地模拟。':'真实平台发送器待接入。'}`})}
async function reconcile(){await act(async()=>{await request('POST','/api/v1/admin/reminders/batches/'+selected.value!.id+(selected.value!.state==='FAILED'?'/retry':'/reconcile'),selected.value!.state==='FAILED'?{evidence:evidence.value}:{state:outcome.value,evidence:evidence.value});selected.value=null;evidence.value='';await load();notice.value='核实结果已记录并审计'})}
async function pause(){await act(async()=>{await request('POST','/api/v1/admin/reminders/rules/'+pausing.value!.id+'/pause',{expectedVersion:pausing.value!.lockVersion,reason:pauseReason.value.trim()});pausing.value=null;pauseReason.value='';await load();notice.value='规则已暂停，原因已记录审计'})}
onMounted(()=>act(load))
</script>
<template><section><div class="title-row"><div><h1>{{ titles[view] }}</h1><p class="muted">日常由系统创建企微任务，工作人员在企微执行；即时使用微信一次性订阅消息。</p></div><button class="secondary" :disabled="busy" @click="act(load)">刷新</button></div><p class="error" role="alert">{{ error }}</p><p role="status">{{ notice }}</p><p v-if="capabilities?.localSimulation" class="badge">本地模拟 · 不连接真实接收人</p><nav v-if="wecomView" class="actions wecom-nav" aria-label="企微运营"><router-link to="/reminders/wecom">任务列表</router-link><router-link to="/reminders/wecom-config">配置</router-link><router-link to="/reminders/wecom-operations">任务处理</router-link><router-link to="/reminders/wecom-logs">执行记录</router-link><router-link to="/reminders/wecom-statistics">统计</router-link></nav><template v-if="config">
<div v-if="view==='wecom-config'" class="panel"><h2>企微接入状态</h2><p>发送器：{{ capabilities?.realProviderReady?'已接入':'待接入联调' }}</p><p>日常任务规划：{{ config.dailyEnabled?'开启':'关闭' }} · 时区 {{ config.timezone }}</p><p>每日时段：{{ config.slots.join(' / ') }}</p><p>模板标识：{{ config.dailyTemplate||'未配置' }}</p><p>账号、绑定规则、回调和模板用途由平台接入团队确认。密钥通过服务器环境配置，本页不接收密钥。</p><div class="actions"><router-link to="/reminders/settings">编辑每日设置</router-link><router-link to="/reminders/templates">编辑模板标识</router-link></div></div>
<div v-if="view==='wecom-operations'" class="panel"><h2>补提与结果核实</h2><p>先在企微核对实际任务与执行记录。已明确失败的任务可填写证据后补提；结果未知的任务必须先核实，避免重复推送。工作人员仍需在企微执行发送。</p><router-link to="/reminders/wecom">进入任务列表处理</router-link><p>需要排查整个任务调度时，进入通道监控执行一次全通道处理；该操作不是只处理企微。</p><router-link to="/reminders/monitor">进入通道监控</router-link></div>
<p v-if="view==='wecom-logs'" class="muted">这里展示企微批次的当前执行状态和平台任务号；结果变更及操作依据可在操作审计中追踪，不等同于平台原始回调日志。</p>
<form v-if="['settings','instant','templates'].includes(view)" class="panel" @submit.prevent="save">
<template v-if="view==='settings'"><label class="check-row"><input v-model="config.dailyEnabled" type="checkbox"/>启用日常任务规划</label><label>业务时区<input v-model="config.timezone" required maxlength="64"/></label><div class="form-grid"><label v-for="(_,i) in config.slots" :key="i">提醒时段 {{ i+1 }}<input v-model="config.slots[i]" type="time" required/></label></div><p class="muted">用户选择其中一个时段。修改时段后按原位置迁移用户选择；当天已建批次不会重复建立。</p></template>
<template v-if="view==='instant'"><label class="check-row"><input v-model="config.instantEnabled" type="checkbox"/>启用即时更新规划</label><p>下一次符合规则的变化使用有效订阅授权发送。确定成功后恢复日常跟踪，失败或结果未知不自动降级。</p><p>管理端不能代替用户授权。关闭规划不会把尚未发送的变化标为成功。</p></template>
<template v-if="view==='templates'"><label>日常任务模板标识<input v-model="config.dailyTemplate" maxlength="128" placeholder="由平台接入团队确认"/></label><label>微信一次性订阅模板 ID<input v-model="config.instantTemplate" maxlength="128" placeholder="填写小程序已审核模板 ID"/></label><p class="muted">此处保存模板标识；正式适配器的字段映射、账号权限和跳转路径仍须联调验证。密钥由服务器环境配置。</p></template><button :disabled="busy">保存设置</button></form>
<div v-if="listing" class="panel"><form v-if="view!=='rules'" class="actions" @submit.prevent="page=1;act(load)"><select v-model="filter" aria-label="任务状态"><option value="">全部状态</option><option v-for="(name,state) in names" :key="state" :value="state">{{ name }}</option></select><button :disabled="busy">查询</button></form><div class="scroll"><table v-if="view==='rules'"><thead><tr><th>用户</th><th>对象</th><th>方式</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{ r.userId }}</td><td>{{ r.targetType==='ARTICLE'?'资讯':'关键词' }} {{ r.title||r.targetId }}</td><td>{{ r.mode==='DAILY'?'日常':'下一次即时' }}</td><td>{{ r.enabled?'启用':'暂停' }}</td><td><button v-if="r.enabled" class="quiet" :disabled="busy" @click="pausing=r;pauseReason=''">暂停规则</button><span v-else class="muted">由用户自主恢复</span></td></tr></tbody></table><table v-else><thead><tr><th>批次 / 用户</th><th>通道 / 内容数</th><th>状态</th><th>平台任务</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{ r.id }}<br/>{{ r.userId }}</td><td>{{ r.channel==='WECom'?'企微日常':'微信即时' }} · {{ r.itemCount }}</td><td>{{ names[r.state]||r.state }}</td><td>{{ r.providerTaskId||'尚未提交' }}</td><td><button v-if="['UNKNOWN','AWAITING_STAFF','PARTIAL','FAILED'].includes(r.state)" class="quiet" @click="selected=r;outcome='SENT'">{{ r.state==='FAILED'?'补提任务':'核实结果' }}</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">暂无记录</p></div><div class="actions"><button class="quiet" :disabled="page===1||busy" @click="page--;act(load)">上一页</button><span>第 {{ page }} 页 · 共 {{ total }} 条</span><button class="quiet" :disabled="page*20>=total||busy" @click="page++;act(load)">下一页</button></div></div>
<div v-if="['statistics','wecom-statistics'].includes(view)&&statistics" class="panel"><div v-if="view==='statistics'" class="user-statistics"><h2>提醒用户</h2><p>历史跟踪用户 {{ statistics.trackedUsers }} · 当前启用用户 {{ statistics.enabledUsers }}</p><p>日常用户 {{ statistics.dailyUsers }} · 即时用户 {{ statistics.instantUsers }}</p><p class="muted">用户按账号去重；当前启用要求账号正常、总开关及至少一条规则开启。日常与即时用户可能重叠，不能相加。历史跟踪包含已暂停规则。</p></div><p v-else class="muted">下列数量为企微批次数量，不等于收件人数或已送达人数。</p><template v-if="!wecomView"><h2>任务创建与确认</h2><p>平台任务创建数 {{ statistics.taskCreated }} · 已确认批次 {{ statistics.confirmed }}</p><p class="muted">确认仅表示有证据完成发送；本地数据为模拟结果。不能将其等同于用户实际阅读。状态分布给出在途、失败和已确认分母。</p><h2>近30天批次趋势</h2><table><thead><tr><th>日期</th><th>通道</th><th>规划数</th><th>已确认</th></tr></thead><tbody><tr v-for="r in statistics.trend" :key="r.day+r.channel"><td>{{ r.day }}</td><td>{{ r.channel }}</td><td>{{ r.created }}</td><td>{{ r.confirmed }}</td></tr></tbody></table><h2>来源分布</h2><p class="muted">按命中来源分别计数，同一变化可以同时命中信息及关键词，不能直接相加。</p><p v-for="r in statistics.sources" :key="r.targetType">{{ r.targetType==='ARTICLE'?'信息更替':'关键词新信息' }} · {{ r.total }}</p><h2>失败与未知原因 Top10</h2><table><thead><tr><th>通道</th><th>原因</th><th>批次</th></tr></thead><tbody><tr v-for="r in statistics.failures" :key="r.channel+r.errorCode"><td>{{ r.channel }}</td><td>{{ r.errorCode }}</td><td>{{ r.total }}</td></tr></tbody></table></template><p v-if="view==='statistics'">启用跟踪 {{ statistics.activeRules }} · 待处理更新 {{ statistics.pendingChanges }}</p><p class="muted">{{ wecomView?'企微批次按状态聚合':'全部批次按通道和状态聚合' }}；本地模拟数据不代表真实送达。</p><table><thead><tr><th>通道</th><th>状态</th><th>数量</th></tr></thead><tbody><tr v-for="r in statRows" :key="r.channel+r.state"><td>{{ r.channel }}</td><td>{{ names[r.state]||r.state }}</td><td>{{ r.total }}</td></tr></tbody></table></div>
<div v-if="['monitor','records'].includes(view)" class="panel"><h2>任务运行</h2><template v-if="health"><p role="status">需处置 {{ health.incidents }} 项 · 在途超时阈值 {{ health.thresholdMinutes }} 分钟</p><table><thead><tr><th>批次</th><th>通道</th><th>状态</th><th>已等待（分钟）</th><th>错误</th></tr></thead><tbody><tr v-for="r in health.items" :key="r.id"><td>{{ r.id }}</td><td>{{ r.channel }}</td><td>{{ names[r.state]||r.state }}</td><td>{{ r.ageMinutes }}</td><td>{{ r.errorCode||'—' }}</td></tr></tbody></table><p class="muted">失败或未知结果立即列入；其他在途状态超时列入。调度日志输出 REMINDER_INCIDENT，由接收团队接告警渠道，未知结果禁止自动重发。</p></template><p class="muted">此操作处理所有已启用通道；正常运行由调度器触发，无须人工持续点击。</p><p>真实平台发送器：{{ capabilities?.realProviderReady?'已接入':'待接入联调' }}</p><p>创建企微任务仅表示待员工执行。无人执行时保持在途，系统不会跨时段重复创建同一批内容。</p><button :disabled="busy" @click="tick">执行一次任务处理</button></div>
</template><form v-if="selected" class="panel" @submit.prevent="reconcile"><h2>核实批次 {{ selected.id }}</h2><label v-if="selected.state!=='FAILED'">核实结果<select v-model="outcome"><option value="SENT">有证据确认已发送</option><option value="FAILED">有证据确认失败</option><option v-if="selected.channel==='WECom'" value="PARTIAL">部分执行，继续等待</option></select></label><label>核实依据<textarea v-model="evidence" required minlength="10" maxlength="1000" placeholder="记录平台查询结果或工单编号；不要填写密钥"/></label><div class="actions"><button :disabled="busy">确认并记录审计</button><button type="button" class="quiet" @click="selected=null">取消</button></div></form><form v-if="pausing" class="panel" @submit.prevent="pause"><h2>暂停用户提醒规则</h2><p>仅暂停此规则后续处理，不撤回已经提交到平台的任务。恢复须由用户操作，管理员不能替用户提供订阅授权。</p><label>暂停原因<textarea v-model="pauseReason" required minlength="10" maxlength="500" placeholder="填写工单、用户请求或处置原因，至少10个字符"/></label><div class="actions"><button :disabled="busy">确认暂停并记录审计</button><button type="button" class="quiet" :disabled="busy" @click="pausing=null">取消暂停</button></div></form></section></template>
<style scoped>.check-row{flex-direction:row;align-items:center}.panel{margin:16px 0}.actions select{width:auto}.wecom-nav{flex-direction:row;flex-wrap:wrap;gap:8px}.wecom-nav a{color:#176b61;background:#fff;border:1px solid #a8bfb2}.wecom-nav a.router-link-exact-active{background:#176b61;color:#fff;border-color:#176b61}</style>
